g:13px 16px;background:#311e27;color:#ffb0b0;border:1px solid #693443;border-radius:9px;margin-bottom:16px;font-size:12px;line-height:1.8}.layout{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(280px,1fr);gap:20px;align-items:start}.aside-title{font-size:24px;font-weight:700;line-height:1.4;margin:12px 0 20px}.members{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:18px 0}.member{background:#0d141e;border:1px solid #273446;border-radius:12px;padding:18px;line-height:1.8;overflow-wrap:anywhere}.avatar-pilot{width:40px;height:40px;display:grid;place-items:center;background:#263d34;color:#c6ff94;margin-bottom:10px;border-radius:12px}.status-text{color:#b9f477;font-size:12px;margin-top:12px}.agreement{padding:18px;border:1px solid #334154;border-radius:10px;line-height:2;font-size:12px}.empty{text-align:center;padding:44px 24px}.empty .submit{max-width:350px}switch{display:block;margin-top:8px}.public-choice{margin-top:20px}.reject-box{border-top:1px solid #263140;margin-top:24px;padding-top:20px}.footer{text-align:center;color:#63758c;font-size:11px;margin-top:28px;letter-spacing:1px}button[disabled]{opacity:.4}.local-note{margin:0 0 18px}
@media(min-width:1000px){.base-grid,.stats-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}
@media(max-width:750px){.pilot{padding:0 16px 28px}.top{height:62px}.brand{font-size:19px}.brand-sub{display:none}.badge{font-size:9px}.tabs{width:auto;display:flex;margin-bottom:20px}.tabs button{flex:1;padding:9px 10px}.panel-pilot{padding:20px 16px;border-radius:13px}.form-grid{gap:0 14px}.layout{grid-template-columns:1fr}.section-detail{font-size:10px}.section-num{font-size:14px}.member{padding:12px}.aside-title{font-size:22px}.choices button{padding:9px 14px}.progress-copy{font-size:11px;margin-left:5px}}
@media(max-width:400px){.form-grid{grid-template-columns:1fr}.section-detail{display:none}}
