.plan-layout .section-num{margin-bottom:18px}
.field-group:has(.level-options),.field-group:has(.style-options){margin-bottom:6px}
@media(max-width:550px){.level-option,.style-option{height:38px;min-height:38px;padding:0 4px;font-size:11px;gap:4px}.plan-layout .panel-pilot{padding-top:18px;padding-bottom:16px}}
.strength-guidance{margin:-5px 0 16px;color:#edc77e;font-weight:500}.local-save-row{display:flex;align-items:center;gap:12px;padding-top:14px;border-top:1px solid #263140;margin-top:2px}.save-local{margin:0;padding:8px 14px;line-height:1.5;font-size:12px;border:1px solid #83a65e;border-radius:8px;background:#b9f4770b;color:#c9edaa}.save-local:focus-visible{outline:2px solid #b9f477;outline-offset:3px}.save-local-note{font-size:11px;color:#8d9fb5}.save-local-note.saved{color:#a9cb8c}.status-strip{display:flex;align-items:center;flex-wrap:wrap;gap:8px;padding:7px 0 12px;margin:0 0 9px;color:#95a6bb;font-size:11px;line-height:1.6}.status-dot{width:5px;height:5px;background:#92a1b5;border-radius:50%;flex-shrink:0}.status-dot.online{background:#b9f477}.status-strip .status-link{display:inline-flex;width:auto;min-height:0;margin:0 0 0 4px;padding:0;border:0;background:none;color:#b9d995;font-size:11px;line-height:1.6;border-radius:0}.status-link:hover{color:#dcffb8}.status-link:focus-visible{outline:1px solid #b9f477;outline-offset:4px}.status-strip.pending{color:#e7c58a}</style>
